code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    candidates = []
    for r in range(h):
        for c in range(w):
            for dr, dc in ((0, 1), (1, 0)):
                cells = [(r + i * dr, c + i * dc) for i in range(3)]
                if all(0 <= rr < h and 0 <= cc < w for rr, cc in cells):
                    vals = tuple(grid[rr][cc] for rr, cc in cells)
                    if all(v != bg for v in vals):
                        candidates.append((cells, vals, dr, dc))
    if not candidates:
        return [row[:] for row in grid]
    # The three-cell colored object is the only contiguous non-background run;
    # prefer a candidate with the greatest number of distinct colors.
    cells, pattern, dr, dc = max(candidates, key=lambda x: (len(set(x[1])), sum(v != bg for v in x[1])))
    object_colors = set(pattern)
    markers = {v for row in grid for v in row if v != bg and v not in object_colors}
    if not markers:
        return [row[:] for row in grid]
    marker = max(markers, key=lambda v: sum(x == v for row in grid for x in row))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, value in enumerate(pattern):
                    rr, cc = r + (i - 1) * dr, c + (i - 1) * dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out
'''
